// `scripts/check-harness-package.sh` reports any difference as drift.
//
// MCP dispatch for the host package. Every tool goes where
// `tool-routes.json` says: a host utility or external engine the package
// supplies, a native HTTP route, or the native MCP catalog. Native tool
// descriptions are relayed from the native `tools/list`, never copied, and
// a native failure is a typed error, never a local substitute.

import { readFileSync } from "node:fs";
import { getRoute, nativeEndpoint, rpc } from "./native-client.mjs";

const TABLE = JSON.parse(readFileSync(new URL("../../tool-routes.json", import.meta.url), "utf8"));

export function routeTable() {
  return TABLE;
}

// Matches theorem-harness-core's selector normalization.
function normalize(value) {
  return String(value ?? "").trim().toLowerCase().replace(/[.\s]+/g, "_");
}

function externalEngine(name, args) {
  return TABLE.external_engines.find((engine) => {
    if (engine.product_tool !== name) return false;
    const key = engine.selector_keys.find((candidate) => typeof args[candidate] === "string");
    return engine.modes.includes(normalize(key === undefined ? "" : args[key]));
  });
}

function receipt(route, { nativeTools = [], owner = route.semantic_owner, transport = route.transport, effect = route.effect }) {
  return {
    schema_version: TABLE.route_schema_version,
    product_tool: route.product_tool,
    kind: route.kind,
    native_tools: nativeTools,
    semantic_owner: owner,
    transport,
    effect: effect ?? "write",
  };
}

function toolResult(content, routeReceipt, isError = false) {
  const result = { content: [{ type: "text", text: JSON.stringify(content, null, 2) }], structuredContent: content };
  if (routeReceipt) result._meta = { [TABLE.receipt_meta_key]: routeReceipt };
  if (isError) result.isError = true;
  return result;
}

function failure(answer) {
  return { error: answer.reason, message: answer.message };
}

// `hostTools` and `httpTools` map a product tool to `{ definition, run? }`;
// `engines` maps an external engine name to `run(args)`. Every key must be a
// route of the matching transport, so a package cannot add its own.
export function createRelay({ serverInfo, hostTools = {}, httpTools = {}, engines = {}, env = process.env }) {
  const routes = new Map(TABLE.routes.map((route) => [route.product_tool, route]));
  for (const [tools, transport] of [[hostTools, "host"], [httpTools, "http"]]) {
    for (const name of Object.keys(tools)) {
      if (routes.get(name)?.transport !== transport) {
        throw new Error(`${name} is not a ${transport} route in tool-routes.json`);
      }
    }
  }
  for (const engine of Object.keys(engines)) {
    if (!TABLE.external_engines.some((declared) => declared.engine === engine)) {
      throw new Error(`${engine} is not an external engine in tool-routes.json`);
    }
  }
  const local = [...Object.values(hostTools), ...Object.values(httpTools)].map((tool) => tool.definition);

  async function callTool(name, args) {
    const route = routes.get(name);
    const engine = externalEngine(name, args);
    if (engine) {
      const run = engines[engine.engine];
      const stamped = receipt(route, { owner: engine.engine, transport: "host", effect: engine.effect });
      if (!run) return toolResult({ error: "external_engine_unavailable", engine: engine.engine }, stamped, true);
      return toolResult(await run(args), stamped);
    }
    if (route?.transport === "host") {
      const stamped = receipt(route, {});
      const tool = hostTools[name];
      if (!tool) return toolResult({ error: "host_utility_unavailable", product_tool: name }, stamped, true);
      return toolResult(await tool.run(args), stamped);
    }
    if (route?.transport === "http") {
      const stamped = receipt(route, { nativeTools: [route.native_target] });
      const answer = await getRoute(route.native_target, args, { env });
      return answer.ok ? toolResult(answer.body, stamped) : toolResult(failure(answer), stamped, true);
    }
    const answer = await rpc("tools/call", { name, arguments: args }, { env });
    if (answer.ok) return answer.result;
    const stamped = route && receipt(route, { nativeTools: route.native_target ? [route.native_target] : [] });
    return toolResult(failure(answer), stamped, true);
  }

  return async function handle(message) {
    const reply = (result) => ({ jsonrpc: "2.0", id: message.id, result });
    const fail = (code, text) => ({ jsonrpc: "2.0", id: message.id, error: { code, message: text } });
    switch (message.method) {
      case "initialize": {
        const result = { protocolVersion: "2024-11-05", serverInfo, capabilities: { tools: {} } };
        if (!nativeEndpoint(env)) {
          result.instructions = "Native Theorem tools are unavailable: no MCP endpoint is configured (THEOREMS_HARNESS_MCP_URL).";
        }
        return reply(result);
      }
      case "tools/list": {
        const native = await rpc("tools/list", {}, { env });
        const nativeTools = native.ok ? native.result.tools ?? [] : [];
        const names = new Set(local.map((tool) => tool.name));
        return reply({ tools: [...local, ...nativeTools.filter((tool) => !names.has(tool.name))] });
      }
      case "tools/call": {
        const { name, arguments: args = {} } = message.params ?? {};
        try {
          return reply(await callTool(String(name ?? ""), args));
        } catch (caught) {
          return fail(-32603, caught instanceof Error ? caught.message : String(caught));
        }
      }
      default:
        return message.id === undefined ? null : fail(-32601, `unsupported method: ${message.method}`);
    }
  };
}
